  /// Public read-only access to all seeded content (used for Daily Culture, collection stats).
  static List<CultureContent> get allContent => List.unmodifiable(_seedData);

  static Future<void> seedCultureContent(FirebaseFirestore firestore) async {
    try {
      final batch = firestore.batch();
      for (final content in _seedData) {
        final ref = firestore.collection('culture_content').doc(content.id);
        batch.set(ref, content.toMap());
      }
      await batch.commit();
    } catch (e) {
      rethrow;
    }
  }

  static Future<bool> hasSeeded(FirebaseFirestore firestore) async {
    try {
      final snapshot = await firestore
          .collection('culture_content')
          .limit(1)
          .get();
      return snapshot.docs.isNotEmpty;
    } catch (e) {
      return false;
    }
  }

  static Future<void> forceReseed(FirebaseFirestore firestore) async {
    final snapshot = await firestore.collection('culture_content').get();
    final batch = firestore.batch();
    for (final doc in snapshot.docs) {
      batch.delete(doc.reference);
    }
    await batch.commit();
    await seedCultureContent(firestore);
  }

  /// Convenience method: seed if collection is empty (no args needed).
  static Future<void> seedIfEmpty() async {
    try {
      final firestore = db;
      final alreadySeeded = await hasSeeded(firestore);
      if (!alreadySeeded) {
        await seedCultureContent(firestore);
      }
    } catch (_) {
      // Non-fatal — app continues without seeded content
    }
  }
}
